rm":"ai","link":"/pe/ai","ebs_sub":[{"code":"ai","label":"Avian Influenza","match":["Suspek Flu Burung Pada Manusia","Flu Burung Pada Manusia"]}],"pe_status":[{"code":"suspek","label":"Suspek"},{"code":"probable","label":"Probabel"},{"code":"konfirmasi","label":"Konfirmasi"}],"death_codes":[],"cfr":{"confirmed":["konfirmasi"],"confirmed_label":"AI konfirmasi","star":[{"code":"suspek","label":"AI suspek*"},{"code":"probable","label":"AI probabel*"}]}},{"code":"antraks","label":"Antraks","disease_codes":["ANTHRAX"],"color":"#6B6766","pe_form":"antraks","link":"/pe/antraks","ebs_sub":[{"code":"antraks","label":"Antraks","match":["Anthraks","Antraks","Anthrax"]}],"pe_status":[{"code":"suspek","label":"Suspek"},{"code":"probabel","label":"Probabel"},{"code":"konfirmasi","label":"Konfirmasi"}],"death_codes":[],"cfr":{"confirmed":["konfirmasi"],"confirmed_label":"Antraks konfirmasi","star":[{"code":"suspek","label":"Antraks suspek*"},{"code":"probabel","label":"Antraks probabel*"}]}},{"code":"lepto","label":"Leptospirosis","disease_codes":["LEPTOSPIROSIS"],"color":"#8A9A00","pe_form":"lepto","link":"/pe/lepto","ebs_sub":[{"code":"lepto","label":"Leptospirosis","match":["Leptospirosis","Suspek Leptospirosis"]}],"pe_status":[{"code":"suspek","label":"Suspek"},{"code":"probable","label":"Probabel"},{"code":"konfirmasi","label":"Konfirmasi"}],"death_codes":[],"cfr":{"confirmed":["konfirmasi"],"confirmed_label":"Leptospirosis konfirmasi","star":[{"code":"suspek","label":"Leptospirosis suspek*"},{"code":"probable","label":"Leptospirosis probabel*"}]}}],"indicators":[{"no":"1–2","name":"Filter periode","status":"sebagian","note":"Memakai filter minggu epid yang sudah ada (tanggal awal/akhir = awal/akhir minggu); kotak tanggal harian belum."},{"no":"3","name":"Lihat sebagai (tingkat akun)","status":"tertunda","note":"Belum ada login/akun (aturan proyek: tanpa login)."},{"no":"4–5","name":"Filter provinsi, kab/kota","status":"tersedia","note":"Acuan wilayah = wilayah unit pelapor (PE) dan wilayah EBS."},{"no":"6","name":"Filter unit pelapor","status":"tertunda","note":"Master sarana (puskesmas/RS) belum tersedia."},{"no":"7","name":"Filter penyakit","status":"sebagian","note":"Penyakit dari master; pilihan \"GHPR saja\"/\"Rabies saja\" belum."},{"no":"8","name":"Reset filter","status":"tersedia","note":"Dari bar filter yang sudah ada."},{"no":"9","name":"Keterangan cakupan","status":"tersedia","note":""},{"no":"10","name":"Menu bagian","status":"tertunda","note":"Menunggu bagian 3–9."},{"no":"11","name":"Palet Kemenkes","status":"sebagian","note":"Warna per penyakit di garis atas card; tema penuh & font Plus Jakarta Sans belum."},{"no":"12–15","name":"Card alert EBS (jumlah, terverifikasi, kasus, kematian)","status":"tersedia","note":"Definisi alert belum disepakati (No. 36): 1 laporan EBS = 1 alert."},{"no":"16–18","name":"Card laporan individu (jumlah, status kasus, kematian)","status":"tersedia","note":"Sumber: Form PE (status Dikirim/Terverifikasi/Final)."},{"no":"19","name":"Tautan dashboard penyakit","status":"sebagian","note":"Dashboard penyakit belum ada; card menautkan ke daftar Form PE."},{"no":"20","name":"Catatan bintang","status":"tersedia","note":""},{"no":"21–35","name":"Tabel CFR + 95% CI Wilson + akhir belum diketahui","status":"tersedia","note":"Pop-up daftar laporan \"Lihat →\" (No. 35) belum."},{"no":"36","name":"Definisi alert","status":"tertunda","note":"Perlu konfirmasi Timker/SKD."},{"no":"37–40","name":"Batang status tindak lanjut alert, % terverifikasi/direspons","status":"sebagian","note":"% terverifikasi ada di card; \"direspons\" belum terdefinisi dan API EBS tidak mengirim tindakan respons B.19–B.39."},{"no":"41–42, 44–45","name":"7-1-7: deteksi, respons, ketiganya","status":"tertunda","note":"API EBS tidak mengirim Tanggal Rumor Diketahui (A.11) maupun tanggal tindakan respons (B.20–B.39)."},{"no":"43","name":"7-1-7: notifikasi ≤1 hari","status":"tersedia","note":"Tanggal dibuat (create_date) − Tanggal (tgl_laporan); alert discarded tidak dihitung."},{"no":"46–49","name":"Pemeriksaan laboratorium (alert EBS)","status":"tertunda","note":"API EBS tidak mengirim Sts Lab No, jumlah diperiksa/positif (B.12–B.18)."},{"no":"50–58","name":"Sebaran wilayah (peta per penyakit, kuartil, drill-down)","status":"tertunda","note":"Data tersedia; dikerjakan pada PR berikutnya (peta lama dipertahankan)."},{"no":"59–64","name":"Tren mingguan","status":"tertunda","note":"Data tersedia; PR berikutnya."},{"no":"65–69, 72–75","name":"Klaster dan epi curve","status":"tertunda","note":"Data klaster PE tersedia (pe_clusters); PR berikutnya. Status aktif/selesai perlu definisi (No. 68)."},{"no":"70–71","name":"Populasi berisiko, attack rate","status":"tertunda","note":"Variabel belum tersedia di sheet."},{"no":"76","name":"% kasus dengan NIK","status":"tersedia","note":"Dari Form PE, tanpa GHPR."},{"no":"77–81","name":"Integrasi NAR-SKDR","status":"tertunda","note":"Butuh API NAR (Pusdatin)."},{"no":"Tambahan","name":"Status alur PE (draf/dikirim/terverifikasi/final)","status":"tersedia","note":"Permintaan Yosua."},{"no":"Tambahan","name":"Cakupan provinsi dan kab/kota pelapor","status":"tersedia","note":"Permintaan Yosua; wilayah dengan ≥ 1 laporan dari sumber mana pun."}]}$dx$)
